# DQ: id, rule, check, layer, action on fail, owner
DQR=[
("Q01","Primary key present and unique","user_id, task_activity_id, reward_id, transaction_id, withdrawal_id, referral_id, event_id non-null and unique","Application + Ingestion","Reject at ingestion; quarantine","Engineering"),
("Q02","ID format","IDs match agreed pattern, no leading/trailing spaces","Ingestion","Trim/reject; log","Engineering"),
("Q03","Allowed status values","status/type/method/unit in approved lists","Application + Raw validation","Quarantine unknown value; alert if >0","Engineering/Data"),
("Q04","Timestamp validity","ISO-8601 UTC, not null where required, not in future (skew tolerance)","Ingestion","Quarantine; never silently coerce","Engineering"),
("Q05","Timestamp ordering","requested_at<=processing_started_at<=finalized_at; started_at<=completed_at","Transformation","Flag; exclude from duration KPIs","Data"),
("Q06","Amount validity","numeric, >0 for transactions, >=0 for rewards; no negatives where inappropriate","Application + Ingestion","Reject","Engineering"),
("Q07","Unit validity","unit in approved list; no cross-unit sums","Transformation/Analytics","Block KPI if mixed","Data"),
("Q08","Referential integrity","Every user_id, task_id, referral FK exists in parent","Transformation","Orphan table; alert","Data"),
("Q09","Duplicate transaction/event","Same transaction_id / event_id seen more than once","Ingestion + Raw","Keep first, log duplicates","Engineering/Data"),
("Q10","Valid state transitions","Withdrawal: requested>processing>completed|rejected; completed>reversed only. Rewards: pending>credited>reversed|corrected","Application + Transformation","Flag impossible transitions","Engineering/Ops"),
("Q11","Reward-wallet reconciliation","Each credited reward has one completed wallet credit","Analytics","Daily reconciliation report (K29)","Data/Finance"),
("Q12","Reversal linkage","reversal rows have original_reward_id / related_transaction_id that exists","Transformation","Flag","Data"),
("Q13","Conditional required fields","failure_category if failed; reason_category if rejected/reversed; final_amount if completed","Application + Transformation","Flag","Engineering"),
("Q14","Consistent naming/case","enums lowercase snake_case; event names from catalogue","Collection + Raw","Normalise in staging; report drift","Data"),
("Q15","Referral stage order","created<=registered<=activated; referrer != referred","Transformation","Flag","Data"),
("Q16","Freshness","Latest event not older than agreed lag","Pipeline monitoring","Alert owner","Data"),
("Q17","Volume anomaly","Daily row count vs trailing average outside tolerance","Pipeline monitoring","Alert (no fixed thresholds invented here)","Data"),
("Q18","Schema drift","New/missing fields vs data dictionary version","Raw","Alert; block load if breaking","Engineering/Data"),
("Q19","PII/secrets screening","No passwords, keys, payment credentials, free text PII in properties_json","Collection + Raw","Quarantine and escalate","Engineering/Security"),
("Q20","Dashboard certification","Dashboard sources only certified tables; metric definitions linked to KPI catalogue","Dashboard","Block uncertified","Data"),
]
